#!/usr/bin/env python3
"""Generate the paper's LaTeX tables from results/.

    python -m experiments.export_latex

Writes booktabs tables into ``paper/tables/``.  The paper ``\\input``s these,
so a number can never be out of date in the write-up while being current in
the repository — re-run ``make reproduce`` and the tables follow.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import Dict, List

from experiments.config import RESULTS_DIR, ROOT

TABLES_DIR = ROOT / "paper" / "tables"

PREAMBLE = (
    "% Generated by experiments/export_latex.py — do not edit by hand.\n"
    "% Regenerate with: make paper-tables\n"
)


def pct(value) -> str:
    return "--" if value is None else f"{value * 100:.1f}"


def num(value, digits: int = 3) -> str:
    return "--" if value is None else f"{value:.{digits}f}"


def signed_pp(value) -> str:
    return "--" if value is None else f"${value * 100:+.1f}$"


def escape(text: str) -> str:
    for old, new in (("&", r"\&"), ("%", r"\%"), ("_", r"\_"), ("#", r"\#")):
        text = text.replace(old, new)
    return text.replace("−", "$-$").replace("↔", r"$\leftrightarrow$")


def load(name: str) -> Dict:
    path = RESULTS_DIR / f"{name}.json"
    if not path.exists():
        raise SystemExit(
            f"{path} is missing — run `make reproduce` before exporting tables."
        )
    return json.loads(path.read_text(encoding="utf-8"))


def baseline_table(systems: List[Dict]) -> str:
    lines = [
        PREAMBLE,
        r"\begin{table*}[t]",
        r"\centering",
        r"\small",
        r"\begin{tabular}{lrrrrrr}",
        r"\toprule",
        r"System & Top-1 & 95\% CI & Top-3 & F1-macro & $\kappa$ & $p$ \\",
        r"\midrule",
    ]
    for s in systems:
        sector = s["sector"]
        ci = sector.get("top1_ci95") or [None, None]
        label = escape(s["label"])
        if s.get("is_oracle"):
            label += r"$^{\dagger}$"
        if s["key"] == "full":
            label = r"\textbf{" + label + "}"
        p = s.get("p_value_vs_full")
        lines.append(
            " & ".join(
                [
                    label,
                    pct(sector["top1_accuracy"]),
                    f"[{pct(ci[0])}, {pct(ci[1])}]",
                    pct(sector["top3_accuracy"]),
                    num(sector["f1_macro"]),
                    num(sector["cohen_kappa"]),
                    "--" if p is None else f"{p:.3f}",
                ]
            )
            + r" \\"
        )
    lines += [
        r"\bottomrule",
        r"\end{tabular}",
        r"\caption{Section classification on the held-out evaluation set "
        r"($n{=}\NEVAL$). Intervals are percentile bootstrap over "
        r"$10{,}000$ resamples; $p$ is an exact McNemar test against our full "
        r"system on the same documents. $\dagger$ uses the gold label "
        r"distribution and is an oracle floor, not a competing method.}",
        r"\label{tab:baselines}",
        r"\end{table*}",
        "",
    ]
    return "\n".join(lines)


def ablation_table(systems: List[Dict]) -> str:
    full = next((s for s in systems if s["key"] == "full"), None)
    base_top1 = full["sector"]["top1_accuracy"] if full else 0.0
    lines = [
        PREAMBLE,
        r"\begin{table}[t]",
        r"\centering",
        r"\small",
        r"\begin{tabular}{lrrr}",
        r"\toprule",
        r"Variant & Top-1 & $\Delta$ & F1-macro \\",
        r"\midrule",
    ]
    for s in systems:
        sector = s["sector"]
        label = escape(s["label"])
        if s["key"] == "full":
            lines.append(
                " & ".join(
                    [r"\textbf{" + label + "}", pct(sector["top1_accuracy"]), "--",
                     num(sector["f1_macro"])]
                )
                + r" \\"
            )
            lines.append(r"\midrule")
            continue
        lines.append(
            " & ".join(
                [
                    label,
                    pct(sector["top1_accuracy"]),
                    signed_pp(sector["top1_accuracy"] - base_top1),
                    num(sector["f1_macro"]),
                ]
            )
            + r" \\"
        )
    lines += [
        r"\bottomrule",
        r"\end{tabular}",
        r"\caption{Component ablation. $\Delta$ is the change in Top-1 accuracy "
        r"against the full system in percentage points.}",
        r"\label{tab:ablation}",
        r"\end{table}",
        "",
    ]
    return "\n".join(lines)


def error_table(report: Dict) -> str:
    flags = report.get("auto_flag_counts", {})
    lines = [
        PREAMBLE,
        r"\begin{table}[t]",
        r"\centering",
        r"\small",
        r"\begin{tabular}{lr}",
        r"\toprule",
        r"Property of the error & Count \\",
        r"\midrule",
    ]
    for flag, count in flags.items():
        lines.append(f"{escape(flag.replace('_', ' '))} & {count} " + r"\\")
    lines += [
        r"\bottomrule",
        r"\end{tabular}",
        r"\caption{Automatically determined properties of the "
        f"{report.get('n_errors', 0)} misclassified documents. "
        r"Manual categories are assigned against the codebook in the "
        r"accompanying repository.}",
        r"\label{tab:errors}",
        r"\end{table}",
        "",
    ]
    return "\n".join(lines)


def macros(baselines: Dict, error_report: Dict) -> str:
    """Numbers the prose cites, as macros, so the text cannot drift either."""
    systems = {s["key"]: s for s in baselines["systems"]}
    full = systems.get("full", {}).get("sector", {})
    tfidf = systems.get("tfidf-nace", {}).get("sector", {})
    ci = full.get("top1_ci95") or [0, 0]
    return "\n".join(
        [
            PREAMBLE,
            r"\newcommand{\NEVAL}{%d}" % full.get("n", 0),
            r"\newcommand{\OursTopOne}{%s\%%}" % pct(full.get("top1_accuracy")),
            r"\newcommand{\OursTopThree}{%s\%%}" % pct(full.get("top3_accuracy")),
            r"\newcommand{\OursFOne}{%s}" % num(full.get("f1_macro")),
            r"\newcommand{\OursCI}{[%s, %s]}" % (pct(ci[0]), pct(ci[1])),
            r"\newcommand{\TfidfTopOne}{%s\%%}" % pct(tfidf.get("top1_accuracy")),
            r"\newcommand{\TfidfFOne}{%s}" % num(tfidf.get("f1_macro")),
            r"\newcommand{\NErrors}{%d}" % error_report.get("n_errors", 0),
            r"\newcommand{\CorpusSize}{9{,}993}",
            r"\newcommand{\NSections}{21}",
            "",
        ]
    )


def main() -> int:
    TABLES_DIR.mkdir(parents=True, exist_ok=True)

    baselines = load("baselines")
    ablation = load("ablation")
    error_report = load("error_analysis")

    written = {
        "baselines.tex": baseline_table(baselines["systems"]),
        "ablation.tex": ablation_table(ablation["systems"]),
        "errors.tex": error_table(error_report),
        "macros.tex": macros(baselines, error_report),
    }
    for name, content in written.items():
        (TABLES_DIR / name).write_text(content, encoding="utf-8")
        print(f"  {Path('paper/tables') / name}")

    print(f"\nWrote {len(written)} files. The paper \\inputs them; nothing to copy by hand.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
